import { CallExpressionShape, isSNScope, Plugin, type Record } from '@servicenow/sdk-build-core'
import { NowIdShape } from './now-id-plugin'

const DB_VIEW = 'sys_db_view'
const DB_VIEW_TABLE = 'sys_db_view_table'
const DB_VIEW_TABLE_FIELD = 'sys_db_view_table_field'
const MAX_VARIABLE_PREFIX_LENGTH = 30

function normalizeViewName(name: string): string {
    return name.toLowerCase().replace(/[^a-z0-9_]/g, '_')
}

export const DatabaseViewPlugin = Plugin.create({
    name: 'DatabaseViewPlugin',

    records: {
        [DB_VIEW]: {
            coalesce: ['name'],
            relationships: {
                [DB_VIEW_TABLE]: {
                    via: 'view',
                    descendant: true,
                    relationships: {
                        [DB_VIEW_TABLE_FIELD]: {
                            via: 'view_table',
                            descendant: true,
                        },
                    },
                },
            },
            toShape(record, { descendants }) {
                const allFieldRecords = descendants.query(DB_VIEW_TABLE_FIELD)

                const tables = descendants.query(DB_VIEW_TABLE).map((table) => {
                    const fieldShapes = allFieldRecords
                        .filter((field) => field.get('view_table').equals(table.getId()))
                        .filter((field) => field.get('field').ifString()?.getValue())
                        .map((field) =>
                            field.transform(({ $ }) => ({
                                $id: $.val(NowIdShape.from(field)),
                                field: $,
                            }))
                        )

                    return table.transform(({ $ }) => ({
                        $id: $.val(NowIdShape.from(table)),
                        table: $,
                        variablePrefix: $.from('variable_prefix'),
                        leftJoin: $.from('left_join').toBoolean().def(false),
                        order: $.toNumber().def(100),
                        whereClause: $.from('where_clause').def(''),
                        active: $.toBoolean().def(true),
                        fields: $.val(fieldShapes.length ? fieldShapes : undefined),
                    }))
                })

                return {
                    success: true,
                    value: new CallExpressionShape({
                        source: record,
                        callee: 'DatabaseView',
                        args: [
                            record.transform(({ $ }) => ({
                                name: $,
                                label: $.def(''),
                                plural: $.def(''),
                                description: $.def(''),
                                tables: $.val(tables),
                            })),
                        ],
                    }),
                }
            },
        },
    },

    shapes: [
        {
            shape: CallExpressionShape,
            fileTypes: ['fluent'],
            async toRecord(callExpression, { config, factory, diagnostics }) {
                if (callExpression.getCallee() !== 'DatabaseView') {
                    return { success: false }
                }

                const arg = callExpression.getArgument(0).asObject()

                const name = arg.get('name').ifString()?.getValue() ?? ''
                const normalizedName = normalizeViewName(name)
                if (name && name !== normalizedName) {
                    diagnostics.error(
                        arg.get('name'),
                        `Database view name '${name}' must already be normalized to '${normalizedName}' (lowercase, non-alphanumeric characters replaced with '_') — the platform rewrites the name on save, which would cause the next build to create a duplicate view instead of updating this one.`
                    )
                }

                const scope = config.scope
                if (name && scope === 'global' && !name.startsWith('u_')) {
                    diagnostics.error(
                        arg.get('name'),
                        `Database view name '${name}' must start with the custom prefix 'u_' in the global scope.`
                    )
                } else if (name && !isSNScope(scope) && scope !== 'global' && !name.startsWith(`${scope}_`)) {
                    diagnostics.error(
                        arg.get('name'),
                        `Database view name '${name}' must start with the scope prefix '${scope}_' to match the current application scope.`
                    )
                }

                const viewRecord = await factory.createRecord({
                    source: callExpression,
                    table: DB_VIEW,
                    properties: arg.transform(({ $ }) => ({
                        name: $,
                        label: $.def(''),
                        plural: $.def(''),
                        description: $.def(''),
                    })),
                })

                const tables = arg.get('tables').ifArray()?.getElements() ?? []

                const seenPrefixes = new Set<string>()
                const seenOrders = new Set<number>()
                const tableRecords: Record[] = []

                for (const tableShape of tables) {
                    const tableObj = tableShape.asObject()
                    const variablePrefix = tableObj.get('variablePrefix').ifString()?.getValue() ?? ''
                    const order = tableObj.get('order').ifNumber()?.getValue() ?? 100

                    if (seenOrders.has(order)) {
                        diagnostics.hint(
                            tableObj.get('order'),
                            `View "${name}" has more than one table with order ${order}.`
                        )
                    } else {
                        seenOrders.add(order)
                    }

                    if (variablePrefix.includes('_')) {
                        diagnostics.error(
                            tableObj.get('variablePrefix'),
                            `Variable prefix '${variablePrefix}' cannot contain an underscore.`
                        )
                    }
                    if (variablePrefix.length > MAX_VARIABLE_PREFIX_LENGTH) {
                        diagnostics.error(
                            tableObj.get('variablePrefix'),
                            `Variable prefix '${variablePrefix}' must be ${MAX_VARIABLE_PREFIX_LENGTH} characters or fewer.`
                        )
                    }
                    if (variablePrefix) {
                        if (seenPrefixes.has(variablePrefix)) {
                            diagnostics.error(
                                tableObj.get('variablePrefix'),
                                `Variable prefix '${variablePrefix}' is used by more than one table in this view. Each joined table must use a unique prefix.`
                            )
                        }
                        seenPrefixes.add(variablePrefix)
                    }

                    const tableRecord = await factory.createRecord({
                        source: tableShape,
                        table: DB_VIEW_TABLE,
                        explicitId: tableObj.get('$id'),
                        properties: tableObj.transform(({ $ }) => ({
                            view: $.val(viewRecord.getId()),
                            table: $,
                            variable_prefix: $.from('variablePrefix'),
                            left_join: $.from('leftJoin').def(false),
                            order: $.def(100),
                            where_clause: $.from('whereClause').def(''),
                            active: $.def(true),
                        })),
                    })

                    const tableName = tableObj.get('table').ifString()?.getValue() ?? ''
                    const fields = tableObj.get('fields').ifArray()?.getElements() ?? []
                    const fieldRecords = await Promise.all(
                        fields.map((fieldShape) => {
                            const fieldObj = fieldShape.asObject()
                            return factory.createRecord({
                                source: fieldShape,
                                table: DB_VIEW_TABLE_FIELD,
                                explicitId: fieldObj.get('$id'),
                                properties: fieldObj.transform(({ $ }) => ({
                                    view_table: $.val(tableRecord.getId()),
                                    field: $,
                                    table: $.val(tableName),
                                })),
                            })
                        })
                    )

                    tableRecords.push(tableRecord.with(...fieldRecords))
                }

                return {
                    success: true,
                    value: viewRecord.with(...tableRecords),
                }
            },
        },
    ],
})
